import openpyxl

# 推斷：舊數量 =「系統帳」數量，新數量 =「實盤」數量；以 (料號, 料件屬性) 為唯一鍵分開比對
wb = openpyxl.load_workbook(INPUT_PATH)

def read_qty_map(ws):
    headers = [cell.value for cell in ws[1]]
    col_idx = {name: i for i, name in enumerate(headers)}
    data = {}
    for row in ws.iter_rows(min_row=2, values_only=True):
        if not row or row[0] is None:
            continue
        mat = row[col_idx['料號']]
        attr = row[col_idx['料件屬性']] or ''
        qty = row[col_idx['數量']]
        # 數量轉為數值，無法轉換時保留 None
        try:
            qty = int(qty)
        except Exception:
            try:
                qty = float(qty)
            except Exception:
                qty = None
        data[(mat, attr)] = qty
    return data

sys_qty = read_qty_map(wb['系統帳'])
act_qty = read_qty_map(wb['實盤'])

diffs = []
for key in sorted(set(sys_qty) | set(act_qty)):
    old_qty = sys_qty.get(key)
    new_qty = act_qty.get(key)
    if old_qty != new_qty:
        diffs.append([key[0], key[1], old_qty, new_qty])

ws_new = wb.create_sheet(title='數量變動')
ws_new.append(['料號', '料件屬性', '舊數量', '新數量'])
for row in diffs:
    ws_new.append(row)

wb.save(OUTPUT_PATH)
